#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section Putnam2023A5. Variable R : realType. Variables A B C : 'rV[R]_2. Hypothesis triangle_ABC_noncollinear : ~ colinear A B C. Hypothesis triangle_ABC_acute : (angle B A C < pi/2) /\ (angle C B A < pi/2) /\ (angle A C B < pi/2). Let O := circumcenter A B C. Let G := (A + B + C) / 3%:R. Let omega := fun P : 'rV[R]_2 => dist P O = dist A O. Let tangent_A := let dir := \matrix_(_,_)(- (A - O) 0) (A - O) 1 in [line A dir]. Let perp_GO_at_G := let dir_GO := O - G in let dir_perp := \matrix_(_,_)((dir_GO) 1) (- (dir_GO) 0) in [line G dir_perp]. Theorem tangent_perp_intersection : exists P : 'rV[R]_2, P \in tangent_A /\ P \in perp_GO_at_G. Proof. Admitted. End
